-- ====================================================================
-- SejarahWira  |  ERA 4: Kaum di Malaysia  |  seed_era4.sql
-- 3 naratif (6 + 6 + 6 babak = 18 babak), setiap babak ada 1 quest, serta 50 soalan.
--
-- SETIAP naratif merangkumi enam topik yang sama: (1) kepelbagaian kaum, (2) petempatan dan ekonomi dahulu di Semenanjung,
-- (3) petempatan kaum Sarawak dan kehidupan bersama kini, (4) alat muzik dan tarian tradisional, (5) permainan tradisional,
-- (6) cerita rakyat (Si Luncai, Legenda Santubong, Legenda Nunuk Ragang). Naratif hanya berbeza pada peranan, suara, watak sampingan dan jenis cabaran.
--
-- Pelajar MERASUK jasad watak rekaan (peranan naratif):
--   Naratif 1 (Rentak Seribu Kaum)      = Pemuzik Warisan (NPC 61)
--   Naratif 2 (Peti Cerita Nenek)       = Nenek Segala Kaum (NPC 62)
--   Naratif 3 (Gelanggang Seribu Kaum)  = Tok Permainan (NPC 63)
-- Baris dialog tanpa penutur (npcID NULL) ialah baris "Pemain" / "kau" yang dituturkan tokoh peranan.
-- Baris naratif tanpa babak (sceneID NULL): 1 = tugas bersejarah, 2 = pembuka pengajaran,
--   3 = pengenalan peranan oleh Pendekar Bayang.
-- Setiap quest ada "aftermath" (Akibat jika salah), pilihan salah jenis 3/5 ada "consequence",
-- dan satu "Giliran Anda" (turns). Data sahaja (tiada jadual atau lajur baharu).
-- Lencana, artifak dan kemajuan era TIDAK disentuh.
--
-- Jalankan SELEPAS seed.sql (tiada NPC sedia ada diperlukan; NPC 61-74 dibuat di sini):
--   mysql --default-character-set=utf8mb4 -u root -p <nama_db> < database/seed_era4.sql
-- Selamat dijalankan berulang kali (kandungan Era 4 lama dipadam dahulu). Era lain tidak disentuh.
--
-- NOTA GAMBAR: latar petempatan_pekan_&_bandar_sarawak.png mempunyai tanda & pada nama fail (ikut nama fail anda).
-- ====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Buang kandungan Era 4 lama (babak, dialog, quest, sokongan dipadam sekali: ON DELETE CASCADE).
DELETE FROM Narrative WHERE eraID = 4;

-- 2. NPC baharu Era 4 (nama fail gambar mengikut folder npc sebenar).
ON DUPLICATE KEY UPDATE name = VALUES(name), biography = VALUES(biography), contribution = VALUES(contribution), asset = VALUES(asset);

-- 3. Naratif

-- 4. Babak (sceneStoryline = kad garis masa dalam suara "kau"; asset = latar belakang)

-- 5. Quest (1 Susun Garis Masa, 2 Cari Bukti, 3 Bantu Tokoh, 4 Padanan, 5 Nyahkod Clue)
--    instruction = taklimat misi, description = objektif pembelajaran

-- 6. Sokongan: baris babak = petunjuk babak; baris quest = bisikan (hint), catatan diari (explanation), pujian (feedback)

-- 7. Dialog: baris peranan (tanpa babak) dan dialog babak

-- 8. Bank soalan Era 4 (50 soalan aneka pilihan, ID 401-450)
ON DUPLICATE KEY UPDATE eraID = VALUES(eraID);

DELETE FROM Question WHERE bankID = 4;


COMMIT;