INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(61, 'Pemuzik Warisan', 'Pemuzik tua yang membawa gambus, sape dan gendang dari kampung ke kampung.', 'Memelihara rentak muzik pelbagai kaum supaya warisan bunyi tidak hilang.', 'pemuzik_ulung.png'),
(62, 'Nenek Segala Kaum', 'Warga emas yang menyimpan cerita petempatan dan legenda setiap kaum (watak rekaan).', 'Menurunkan cerita kaum kepada cucu-cucu supaya mereka mengenali jiran sendiri.', 'nenek_dahulu.png'),
(63, 'Tok Permainan', 'Penjaga gelanggang permainan tradisional yang menyatukan kanak-kanak segala kaum.', 'Memastikan permainan warisan terus dimainkan oleh semua kaum bersama-sama.', 'tok_permainan.png'),
(64, 'Aishah', 'Gadis Melayu yang peramah dan petah bertanya (watak rekaan).', 'Mewakili anak muda Melayu yang ingin mengenali kaum lain.', 'gadis_melayu.png'),
(65, 'Kavitha', 'Gadis India yang ceria dan pandai menari (watak rekaan).', 'Mewakili anak muda India yang bangga dengan warisan kaumnya.', 'gadis_india.png'),
(66, 'Linda', 'Gadis Kadazandusun dari Sabah yang gemar bercerita (watak rekaan).', 'Mewakili anak muda Sabah yang menjaga cerita dan tarian kaumnya.', 'gadis_sabah.png'),
(67, 'Jenny', 'Gadis dari Sarawak yang bersemangat dan suka berjenaka (watak rekaan).', 'Mewakili anak muda Sarawak yang bangga dengan kaum dan negerinya.', 'gadis_sarawak.png'),
(68, 'Apai Iban', 'Orang tua Iban yang gagah dan pandai bercerita tentang lembah sungai (watak rekaan).', 'Mewakili masyarakat Iban di lembah sungai Sarawak.', 'sarawakian.png'),
(69, 'Ah Meng', 'Pemuda Cina yang bertenaga dan suka bergurau (watak rekaan).', 'Mewakili anak muda Cina yang suka mencuba semua permainan dan muzik.', 'lengchai_cina.png'),
(70, 'Tok Batin', 'Orang tua Orang Asli yang tenang dan mahir hasil hutan (watak rekaan).', 'Mewakili masyarakat Orang Asli di pedalaman Semenanjung.', 'orang_tradisi_lama.png'),
(71, 'Pak Bajau', 'Lelaki Bajau dari Sabah yang peramah (watak rekaan).', 'Mewakili kaum lain di Sabah dalam kepelbagaian kaum.', 'orang_bajau.png'),
(72, 'Si Luncai', 'Watak cerita rakyat yang bijak memperdaya dengan labu-labunya.', 'Melambangkan akal yang bijak dalam cerita rakyat Melayu.', 'si_luncai.png'),
(73, 'Puteri Santubong', 'Puteri kayangan dalam legenda Santubong yang pandai menenun.', 'Mewakili legenda asal usul Gunung Santubong di Sarawak.', 'puteri_santubong.png'),
(74, 'Murid Sekolah', 'Murid yang gemar bertanya dan bertenaga (watak rekaan).', 'Mewakili generasi muda yang mewarisi budaya pelbagai kaum.', 'budak_gajet.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(401, 'Rentak Seribu Kaum', 4, 'Masuki peranan seorang pemuzik tua yang mengembara dari kampung ke kampung membawa gambus, sape dan gendang. Dalam setiap rentak kau mengenali kepelbagaian kaum, petempatan dan ekonomi mereka dahulu dan kini, alat muzik dan tarian, permainan tradisional serta cerita rakyat.'),
(402, 'Peti Cerita Nenek', 4, 'Masuki peranan Nenek Segala Kaum yang membuka peti cerita lamanya. Dari satu laci ke satu laci, kau mengajar cucu-cucu tentang kepelbagaian kaum, petempatan dan ekonomi dahulu serta kini, alat muzik dan tarian, permainan tradisional dan tiga cerita rakyat.'),
(403, 'Gelanggang Seribu Kaum', 4, 'Masuki peranan Tok Permainan yang menjaga gelanggang tempat semua kaum bermain bersama. Setiap pusingan membawa kau mengenali kepelbagaian kaum, petempatan dan ekonomi dahulu serta kini, alat muzik dan tarian, permainan tradisional dan tiga cerita rakyat.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e4_n1_s1', 'Padang taman perumahan yang meriah. Kau, pemuzik tua, mengetuk gendang kecil sambil dikelilingi anak muda pelbagai kaum yang mahu tahu berapa banyak kaum yang ada di Malaysia.', 1, 401, 'petempatan_semua_kini.png'),
('e4_n1_s2', 'Kampung tepi pantai dan sungai pada zaman dahulu. Kau, pemuzik tua, singgah bermalam dan mendengar sendiri kerja dan tempat tinggal setiap kaum.', 2, 401, 'petempatan_melayu_dahulu.png'),
('e4_n1_s3', 'Lembah sungai di Sarawak yang berkilau. Kau, pemuzik tua, menaiki perahu bersama Apai Iban untuk memahami petempatan dan kerja kaum di Sarawak.', 3, 401, 'petempatan_lembah_sungai_sarawak.png'),
('e4_n1_s4', 'Padang perayaan yang riuh dengan pentas lima kaum. Kau, pemuzik tua, memegang gambus dan mencari alat muzik serta tarian setiap kaum pada pentas masing-masing.', 4, 401, 'alat_muzik_dan_tarian_tradisional.png'),
('e4_n1_s5', 'Anjung rumah, laman dan padang lapang di satu petang. Kau, pemuzik tua, mengetuk gendang menjadi pengiring permainan tradisional kanak-kanak.', 5, 401, 'permainan_tradisional.png'),
('e4_n1_s6', 'Tepi pantai yang berkilau di bawah matahari. Kau, pemuzik tua, menyanyikan lagu Si Luncai sambil perahu bergerak ke tengah laut.', 6, 401, 'si_luncai.png'),
('e4_n2_s1', 'Beranda rumah di taman perumahan yang riuh. Kau, si nenek, membuka peti cerita lamamu dan cucu-cucu pelbagai kaum berebut duduk di hadapan peti itu.', 1, 402, 'petempatan_semua_kini.png'),
('e4_n2_s2', 'Laci kedua peti nenek terbuka dan lukisan kampung lama muncul seperti hidup. Kau, si nenek, bercerita tentang tempat tinggal dan kerja pelbagai kaum di Semenanjung pada zaman dahulu.', 2, 402, 'petempatan_cina_dahulu.png'),
('e4_n2_s3', 'Laci ketiga membawa kau ke pedalaman Sarawak melalui lukisan lama. Kau, si nenek, bercerita tentang petempatan kaum Sarawak dan bagaimana semua kaum kini hidup bersama.', 3, 402, 'petempatan_pedalaman_sarawak_dahulu.png'),
('e4_n2_s4', 'Laci keempat berbunyi ting-tung sebaik dibuka, dan pentas lima kaum muncul di atas lukisan. Kau, si nenek, memadankan alat muzik dan tarian setiap kaum untuk cucu-cucumu.', 4, 402, 'alat_muzik_dan_tarian_tradisional.png'),
('e4_n2_s5', 'Laci kelima menjadi padang kecil di atas lantai. Kau, si nenek, mencari permainan tradisional pada tiga tempat, anjung, laman dan kawasan lapang, bersama cucu-cucumu.', 5, 402, 'permainan_tradisional.png'),
('e4_n2_s6', 'Laci terakhir menyimpan tiga gulung lukisan. Kau, si nenek, membuka satu persatu, Si Luncai, Santubong dan Nunuk Ragang, sambil cucu-cucu mendengar dengan mata terbeliak.', 6, 402, 'puteri_santubong.png'),
('e4_n3_s1', 'Pintu masuk gelanggang. Kau, Tok Permainan, memegang wisel besar dan menyambut pemain dari pelbagai kaum yang berbaris mendaftar pasukan.', 1, 403, 'petempatan_semua_dahulu.png'),
('e4_n3_s2', 'Gelanggang pusingan kedua menunjukkan lukisan kampung lama. Kau, Tok Permainan, menjadi pengadil kuiz petempatan dan kerja pelbagai kaum di Semenanjung pada zaman dahulu.', 2, 403, 'petempatan_orang_asli_dahulu.png'),
('e4_n3_s3', 'Pusingan ketiga di tepi sungai. Kau, Tok Permainan, membentangkan garis masa kaum Sarawak dari zaman dahulu hingga kini kepada pemain-pemain.', 3, 403, 'petempatan_pekan_&_bandar_sarawak.png'),
('e4_n3_s4', 'Pusingan keempat ialah pertandingan pentas. Kau, Tok Permainan, menjadi pengadil muzik dan tarian lima kaum yang bertanding di pentas masing-masing.', 4, 403, 'alat_muzik_dan_tarian_tradisional.png'),
('e4_n3_s5', 'Pusingan kelima di gelanggang utama. Kau, Tok Permainan, membaca papan skor lama yang menyenaraikan permainan tradisional mengikut tempat dimainkan.', 5, 403, 'permainan_tradisional.png'),
('e4_n3_s6', 'Pusingan akhir ialah gelanggang cerita. Kau, Tok Permainan, bergilir dengan tiga tokoh cerita rakyat dan mencari bukti legenda Nunuk Ragang pada gambar besar.', 6, 403, 'nunuk_ragang.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(401, 'e4_n1_s1', 'Bantu Pemuzik Menjawab Soalan Kaum', 'Bantu pemuzik menjawab soalan anak muda tentang kaum lain di Sabah dan Sarawak.', '3', 'Mengenal pasti kepelbagaian kaum di Malaysia.', '{"prompt": "Linda bertanya kepada kau: yang manakah senarai kaum lain di Sabah dan kaum lain di Sarawak?", "options": [{"text": "Sabah: Murut, Rungus, Iranun dan Bajau. Sarawak: Melayu, Kenyah, Melanau dan Bidayuh.", "isCorrect": true}, {"text": "Sabah: Melayu, Kenyah, Melanau dan Bidayuh. Sarawak: Murut, Rungus, Iranun dan Bajau.", "isCorrect": false, "consequence": "Linda menulis senarai yang tertukar. Anak-anak muda menyalin dan mula percaya kaum Sabah dan Sarawak sama sahaja."}, {"text": "Sabah: Iban, Sikh, Serani dan Chetti. Sarawak: Siam, Orang Asli, Baba dan Nyonya.", "isCorrect": false, "consequence": "Senarai itu bercampur aduk. Murid-murid keliru dan tidak lagi tahu kaum mana tinggal di mana."}], "aftermath": "Senarai kaum tertukar. Anak-anak muda pulang dengan nama kaum yang tersalah tempat.", "turns": [{"after": 4, "options": [{"text": "Murut, Rungus, Iranun dan Bajau.", "isCorrect": true, "reaction": "Tepat, pak cik! Linda bersorak dan Pak Bajau melambai dari belakang. Papan skor bersinar!"}, {"text": "Melayu, Kenyah, Melanau dan Bidayuh.", "isCorrect": false, "reaction": "Itu kaum lain di Sarawak, pak cik! Jenny ketawa dan Linda menggeleng. Sabah kena tunggu giliran."}, {"text": "Iban, Sikh, Serani dan Chetti.", "isCorrect": false, "reaction": "Pak cik, mereka bukan kumpulan kaum lain di Sabah. Papan skor jadi kelam-kabut!"}], "clue": "Linda menyebut kaum lain di Sabah selepas Kadazandusun. Dengar semula empat nama yang dia sebut."}]}'),
(402, 'e4_n1_s2', 'Padanan Kaum dan Kegiatan Dahulu', 'Padankan setiap kaum dengan petempatan dan kegiatan ekonominya dahulu.', '4', 'Mengenal pasti petempatan dan kegiatan ekonomi kaum di Semenanjung dahulu.', '{"pairs": [{"text": "Melayu", "pair": 1}, {"text": "Kampung, pesisir pantai dan sungai; petani, nelayan, peniaga kecil", "pair": 1}, {"text": "Cina", "pair": 2}, {"text": "Pekan dan bandar; pelombong dan peniaga", "pair": 2}, {"text": "India", "pair": 3}, {"text": "Ladang dan pinggir bandar; pekerja ladang dan pelabuhan", "pair": 3}, {"text": "Orang Asli", "pair": 4}, {"text": "Pedalaman; kraf tangan, berburu dan memungut hasil hutan", "pair": 4}], "aftermath": "Kegiatan kaum tertukar tempat. Rentak lagu kampung pun berantakan dan penonton bingung.", "turns": [{"after": 4, "options": [{"text": "Orang Cina, sebagai pelombong dan peniaga.", "isCorrect": true, "reaction": "Tepat, pak cik! Ah Meng membunyikan loceng kedai. KLING-KLING!"}, {"text": "Orang Melayu, sebagai petani dan nelayan.", "isCorrect": false, "reaction": "Itu kerja orang Melayu di kampung dan pesisir, pak cik. Ah Meng mengaru kepala dan loceng kedai terdiam."}, {"text": "Orang India, sebagai pekerja ladang.", "isCorrect": false, "reaction": "Itu tentang ladang dan pinggir bandar, pak cik. Bukan pekan, jadi jawapan itu tersasar."}], "clue": "Pelombong dan peniaga banyak berada di pekan dan bandar."}]}'),
(403, 'e4_n1_s3', 'Nyahkod Nota Lama Sarawak', 'Baca nota lama dan tentukan kegiatan ekonomi kaum Melayu, Melanau dan Kedayan di pekan dan bandar Sarawak.', '5', 'Mengenal pasti petempatan dan ekonomi kaum di Sarawak dahulu serta kehidupan bersama kini.', '{"clueText": "Nota lama menulis: Bidayuh, Kenyah dan Kelabit tinggal di pedalaman. Iban dan Bisaya tinggal di lembah sungai sebagai petani. Melayu, Melanau dan Kedayan tinggal di pekan dan bandar. Ekonomi mereka sudah luntur dan tidak kelihatan.", "options": [{"text": "Pedagang, pembuat perahu dan pengusaha sagu.", "isCorrect": true}, {"text": "Menanam padi sawah dan padi bukit di pedalaman.", "isCorrect": false, "consequence": "Nota itu ditulis semula dengan maksud yang salah. Pembaca menyangka orang pekan dan bandar bertani padi bukit."}, {"text": "Menoreh getah dan bekerja di pelabuhan di ladang.", "isCorrect": false, "consequence": "Catatan itu bercampur dengan kegiatan di Semenanjung. Pembaca keliru dengan sejarah ekonomi Sarawak."}], "aftermath": "Nota lama disalah baca. Kegiatan kaum Sarawak dicatat dengan tersasar.", "turns": [{"after": 4, "options": [{"text": "Pedagang, pembuat perahu dan pengusaha sagu.", "isCorrect": true, "reaction": "Tepat, pak cik! Perahu kita meluncur laju dan kami bersorak!"}, {"text": "Menanam padi sawah dan padi bukit.", "isCorrect": false, "reaction": "Itu kerja kaum di pedalaman, pak cik. Perahu kita tersangkut di pasir kerana jawapan itu."}, {"text": "Pekerja ladang getah dan pekerja pelabuhan.", "isCorrect": false, "reaction": "Itu kerja di Semenanjung, pak cik. Apai ketawa dan Jenny menggeleng."}], "clue": "Nota lama menyebut kaum Melayu, Melanau dan Kedayan berada di pekan dan bandar."}]}'),
(404, 'e4_n1_s4', 'Cari Bukti Pentas Lima Kaum', 'Cari alat muzik dan tarian bagi lima kaum pada gambar padang perayaan.', '2', 'Mengenal pasti alat muzik dan tarian tradisional kaum Melayu, Cina, India, Sarawak dan Sabah.', '{"bgImage": "../assets/gameAsset/background/alat_muzik_dan_tarian_tradisional.png", "hotspots": [{"name": "Pentas Melayu: gambus dan angklung; tarian makyung dan zapin", "top": "25%", "left": "32%"}, {"name": "Tarian singa: gendang dan bo; masyarakat Cina", "top": "20%", "left": "52%"}, {"name": "Pentas India: veenai dan talam; tarian bharatanatyam", "top": "62%", "left": "35%"}, {"name": "Tarian ngajat: sape dan engkerurai; masyarakat Sarawak", "top": "62%", "left": "60%"}, {"name": "Tarian sumazau: kulintangan dan sompotan; masyarakat Sabah", "top": "52%", "left": "71%"}], "aftermath": "Alat muzik dan tarian bercampur antara pentas. Persembahan terhenti dan penonton pulang dengan salah faham.", "turns": [{"after": 4, "options": [{"text": "Pentas kaum Sabah.", "isCorrect": true, "reaction": "Tepat, pak cik! Gong Sabah berbunyi dan penonton bertepuk tangan!"}, {"text": "Pentas kaum Sarawak.", "isCorrect": false, "reaction": "Itu tarian ngajat, pak cik! Sumazau dari Sabah. Penari ngajat pun tercengang."}, {"text": "Pentas kaum Cina.", "isCorrect": false, "reaction": "Pak cik, tarian singa dari pentas Cina, bukan sumazau. Singa itu menggeleng-geleng kepala!"}], "clue": "Sumazau ialah tarian dari Sabah, bukan dari Sarawak."}]}'),
(405, 'e4_n1_s5', 'Padanan Tempat Permainan Tradisional', 'Padankan permainan tradisional dengan tempat ia dimainkan.', '4', 'Mengenal pasti permainan anjung, laman dan kawasan lapang.', '{"pairs": [{"text": "Permainan anjung", "pair": 1}, {"text": "Congkak, batu seremban, go, yoyo cina, chaturangam, paramapadham", "pair": 1}, {"text": "Permainan laman", "pair": 2}, {"text": "Sepak raga, chap teh dan kabaddi", "pair": 2}, {"text": "Permainan kawasan lapang", "pair": 3}, {"text": "Wau, tibau, sepak manggis dan gasing", "pair": 3}], "aftermath": "Permainan dipadankan dengan tempat yang salah. Kanak-kanak bermain di tempat yang tidak sesuai dan pertandingan berhenti.", "turns": [{"after": 5, "options": [{"text": "Kawasan lapang.", "isCorrect": true, "reaction": "Tepat, pak cik! Wau saya terbang tinggi dan kawan-kawan bersorak!"}, {"text": "Anjung rumah.", "isCorrect": false, "reaction": "Anjung untuk permainan papan dan batu, pak cik. Wau saya tersangkut di tiang rumah!"}, {"text": "Laman rumah sahaja.", "isCorrect": false, "reaction": "Laman untuk sepak raga dan chap teh, pak cik. Wau perlu ruang lebih luas."}], "clue": "Wau perlu ruang luas dan angin kencang, bukan di anjung atau laman."}]}'),
(406, 'e4_n1_s6', 'Susun Tipu Helah Si Luncai', 'Susun peristiwa dalam cerita Si Luncai mengikut urutan yang betul.', '1', 'Memahami cerita rakyat Si Luncai, Legenda Santubong dan Legenda Nunuk Ragang.', '{"timelineItems": [{"id": 1, "year": "Dihukum raja", "text": "Si Luncai dijatuhi hukuman raja kerana mempermain-mainkan raja dan pembesar", "why": "Hukuman itu mencetuskan seluruh cerita."}, {"id": 2, "year": "Dalam perahu", "text": "Si Luncai dimasukkan ke dalam guni dan perahu menuju ke tengah laut", "why": "Dalam guni, dia melihat labu air di dalam perahu."}, {"id": 3, "year": "Menyanyi", "text": "Si Luncai menyanyi dan pesuruh raja ikut menyanyi sehingga leka", "why": "Kelekaan memberi peluang kepada Si Luncai."}, {"id": 4, "year": "Tipu helah", "text": "Si Luncai mengisi labu ke dalam guni dan terjun berenang dengan labu air", "why": "Pesuruh raja kemudian mencampak guni itu tanpa menyedari dia selamat."}], "aftermath": "Urutan cerita tertukar. Anak-anak mendengar cerita yang kelam-kabut dan kehilangan pengajaran akal yang bijak.", "turns": [{"after": 7, "options": [{"text": "Keluar dari guni, isi labu dalam guni, lalu terjun berenang dengan labu air.", "isCorrect": true, "reaction": "Tepat! Aku menjadi pelari laut yang terbaik! Pesuruh raja pun campak guni berisi labu itu!"}, {"text": "Terus menanti pesuruh raja membuka guni dan melepaskan aku di tengah laut itu.", "isCorrect": false, "reaction": "Aduh, Luncai tak sabar menunggu! Pesuruh raja tak akan buka guni, mereka hanya mahu campakkan ke laut."}, {"text": "Terjun ke laut dengan guni di belakang tanpa membawa sebarang labu air.", "isCorrect": false, "reaction": "Tanpa labu, Luncai tenggelam, pemuzik! Labu air itulah yang menyelamatkan aku."}], "clue": "Luncai menipu pesuruh raja dengan mengisi labu ke dalam guni, kemudian terjun dengan labu air."}]}'),
(407, 'e4_n2_s1', 'Padanan Kad Kaum Nenek', 'Padankan setiap kumpulan kaum dengan senarai namanya.', '4', 'Mengenal pasti kepelbagaian kaum di Semenanjung, Sabah dan Sarawak.', '{"pairs": [{"text": "Kaum utama Semenanjung", "pair": 1}, {"text": "Melayu, Cina, India, Siam dan Orang Asli", "pair": 1}, {"text": "Peranakan dan lain-lain", "pair": 2}, {"text": "Chetti, Baba dan Nyonya, Sikh dan Serani", "pair": 2}, {"text": "Kaum utama Sabah dan Sarawak", "pair": 3}, {"text": "Kadazandusun (Sabah) dan Iban (Sarawak)", "pair": 3}, {"text": "Kaum lain di Sabah", "pair": 4}, {"text": "Murut, Rungus, Iranun dan Bajau", "pair": 4}, {"text": "Kaum lain di Sarawak", "pair": 5}, {"text": "Melayu, Kenyah, Melanau dan Bidayuh", "pair": 5}], "aftermath": "Kad kaum tersalah laci. Cucu-cucu pulang dengan senarai yang bercampur dan jiran pun dikenali dengan nama salah.", "turns": [{"after": 5, "options": [{"text": "Murut, Rungus, Iranun dan Bajau.", "isCorrect": true, "reaction": "Betul, nenek! Pak Bajau melambai dan cucu-cucu bersorak. Kad bertukar emas!"}, {"text": "Melayu, Kenyah, Melanau dan Bidayuh.", "isCorrect": false, "reaction": "Itu kaum lain di Sarawak, nenek! Kad itu berpatah balik ke laci Sarawak."}, {"text": "Chetti, Baba dan Nyonya, Sikh dan Serani.", "isCorrect": false, "reaction": "Kaum itu di Semenanjung, nenek! Murid-murid tergelak sebab kad tersesat laci."}], "clue": "Kaum lain di Sabah disebut Linda bersama Pak Bajau, selepas Kadazandusun."}]}'),
(408, 'e4_n2_s2', 'Nyahkod Nota Lama Semenanjung', 'Baca nota lama dan tentukan kegiatan ekonomi masyarakat India dahulu.', '5', 'Mengenal pasti petempatan dan kegiatan ekonomi Melayu, Cina, India dan Orang Asli dahulu.', '{"clueText": "Nota lama menulis: Melayu di kampung dan pesisir (petani, nelayan). Cina di pekan dan bandar (pelombong, peniaga). Orang Asli di pedalaman. India di ladang dan pinggir bandar, tetapi kegiatan ekonominya sudah luntur dan hilang.", "options": [{"text": "Pekerja ladang, peniaga kecil-kecilan dan pekerja pelabuhan.", "isCorrect": true}, {"text": "Pelombong bijih timah dan peniaga di pekan dan bandar.", "isCorrect": false, "consequence": "Nota ditulis semula dengan kegiatan kaum Cina. Cucu-cucu menyangka orang India dahulu melombong di pekan."}, {"text": "Berburu dan memungut hasil hutan di pedalaman jauh.", "isCorrect": false, "consequence": "Catatan itu bercampur dengan kegiatan Orang Asli. Cucu-cucu tidak lagi tahu apa kerja orang India di ladang."}], "aftermath": "Nota lama disalah baca. Kegiatan ekonomi kaum ditulis pada tempat yang salah.", "turns": [{"after": 5, "options": [{"text": "Pekerja ladang, peniaga kecil-kecilan dan pekerja pelabuhan.", "isCorrect": true, "reaction": "Tepat, nenek! Kavitha mengangguk. Nota lama bercahaya semula!"}, {"text": "Pelombong bijih dan peniaga di pekan dan bandar besar.", "isCorrect": false, "reaction": "Itu kerja orang Cina di bandar, nenek. Kavitha menggaru kepala dan nota lama terdiam."}, {"text": "Kraf tangan, berburu dan memungut hasil di dalam hutan.", "isCorrect": false, "reaction": "Itu Orang Asli di pedalaman, nenek. Tok Batin ketawa dan Kavitha memuncung."}], "clue": "Nota lama menyebut India berada di ladang dan pinggir bandar, jauh dari hutan dan pekan."}]}'),
(409, 'e4_n2_s3', 'Bantu Nenek Menjawab Apai', 'Bantu nenek menjawab soalan Apai tentang kaum dan kerja di lembah sungai Sarawak.', '3', 'Mengenal pasti petempatan dan ekonomi kaum Sarawak dahulu serta kehidupan bersama kini.', '{"prompt": "Apai bertanya kepada kau: kaum manakah tinggal di lembah sungai Sarawak, apa kerjanya, dan bagaimana keadaan rakyat kini?", "options": [{"text": "Iban dan Bisaya bertani; kini semua kaum bekerja bersama dan tinggal dalam satu kawasan perumahan.", "isCorrect": true}, {"text": "Bidayuh, Kenyah dan Kelabit bertani padi bukit; kini setiap kaum tinggal berasingan di pedalaman.", "isCorrect": false, "consequence": "Cucu-cucu menyangka kaum lembah sungai ialah kaum pedalaman. Mereka juga percaya kini semua masih berpisah."}, {"text": "Melayu, Melanau dan Kedayan berdagang; kini setiap kaum tinggal di tempat berasingan.", "isCorrect": false, "consequence": "Cucu-cucu mencatat pekan dan bandar sebagai lembah sungai. Mereka kehilangan pelajaran tentang hidup bersama."}], "aftermath": "Petempatan Sarawak tercatat salah. Cucu-cucu menyangka rakyat kini masih tinggal berasingan.", "turns": [{"after": 5, "options": [{"text": "Iban dan Bisaya, sebagai petani.", "isCorrect": true, "reaction": "Tepat, nenek! Apai mengayuh dayung dan Jenny bertepuk tangan!"}, {"text": "Bidayuh, Kenyah dan Kelabit, sebagai pengutip hasil hutan.", "isCorrect": false, "reaction": "Itu di pedalaman, nenek. Apai ketawa dan dayungnya tersangkut di akar."}, {"text": "Melayu, Melanau dan Kedayan, sebagai pembuat perahu.", "isCorrect": false, "reaction": "Itu di pekan dan bandar, nenek. Perahu Apai pun hampir berpusing!"}], "clue": "Lembah sungai ialah tempat Iban dan Bisaya, kerjanya bertani."}]}'),
(410, 'e4_n2_s4', 'Padanan Alat Muzik dan Tarian', 'Padankan setiap kaum dengan alat muzik dan tarian tradisionalnya.', '4', 'Mengenal pasti alat muzik dan tarian tradisional pelbagai kaum.', '{"pairs": [{"text": "Melayu", "pair": 1}, {"text": "Angklung, gambus, nafiri, geduk; makyung dan zapin", "pair": 1}, {"text": "Cina", "pair": 2}, {"text": "Gendang, bo, liu qin, seruling; tarian singa", "pair": 2}, {"text": "India", "pair": 3}, {"text": "Pullangkulal, talam, mattalam, veenai; bharatanatyam", "pair": 3}, {"text": "Sarawak", "pair": 4}, {"text": "Sape, engkerurai, engkerumong; ngajat", "pair": 4}, {"text": "Sabah", "pair": 5}, {"text": "Kulintangan, sompotan, tongkungan, tontog; sumazau", "pair": 5}], "aftermath": "Alat muzik tertukar antara kaum. Pentas berbunyi sumbang dan penonton pulang dengan kenangan yang salah.", "turns": [{"after": 4, "options": [{"text": "Tarian ngajat ialah tarian Sarawak, sumazau tarian Sabah.", "isCorrect": true, "reaction": "Tepat, nenek! Linda dan Jenny bertukar senyum, dua tarian di pentas masing-masing."}, {"text": "Tarian sumazau ialah tarian Sarawak, ngajat tarian Sabah.", "isCorrect": false, "reaction": "Tertukar, nenek! Kedua-dua penari berhenti dan mengerut dahi."}, {"text": "Tarian ngajat dan sumazau kedua-duanya tarian Cina.", "isCorrect": false, "reaction": "Itu tarian singa, nenek. Singa terkejut kerana dua penari datang ke pentas Cina!"}], "clue": "Ngajat bersama sape, sumazau bersama kulintangan. Satu Sarawak, satu Sabah."}]}'),
(411, 'e4_n2_s5', 'Cari Bukti Permainan Tiga Tempat', 'Cari permainan tradisional di anjung, laman dan kawasan lapang pada gambar.', '2', 'Mengenal pasti permainan tradisional anjung, laman dan kawasan lapang.', '{"bgImage": "../assets/gameAsset/background/permainan_tradisional.png", "hotspots": [{"name": "Permainan anjung: congkak, batu seremban, go dan chaturangam", "top": "28%", "left": "15%"}, {"name": "Permainan laman: sepak raga", "top": "48%", "left": "45%"}, {"name": "Permainan lapang: wau di langit", "top": "8%", "left": "58%"}, {"name": "Permainan lapang: gasing dan tibau", "top": "50%", "left": "58%"}, {"name": "Permainan laman: chap teh dan kabaddi", "top": "58%", "left": "45%"}], "aftermath": "Permainan terletak di tempat salah. Kanak-kanak bermain tanpa ruang dan pertandingan terhenti.", "turns": [{"after": 4, "options": [{"text": "Wau dan gasing, di kawasan lapang.", "isCorrect": true, "reaction": "Tepat, nenek! Wau naik tinggi dan gasing berpusing laju. Hebat!"}, {"text": "Congkak dan batu seremban, di kawasan lapang.", "isCorrect": false, "reaction": "Itu permainan anjung, nenek! Congkak jatuh bergolek dari padang, haha!"}, {"text": "Chap teh dan kabaddi, di anjung rumah.", "isCorrect": false, "reaction": "Itu permainan laman, nenek! Ah Meng menggeleng sebab kabaddi tak muat di anjung."}], "clue": "Wau dan gasing perlukan ruang luas, jadi ia di kawasan lapang."}]}'),
(412, 'e4_n2_s6', 'Nyahkod Gulung Santubong', 'Baca gulung lama dan tentukan apa yang menyebabkan Gunung Santubong sumbing.', '5', 'Memahami cerita rakyat Si Luncai, Legenda Santubong dan Legenda Nunuk Ragang.', '{"clueText": "Gulung lama menulis: Puteri Santubong menenun, Puteri Sejinjang menumbuk padi. Mereka bertelingkah kerana Putera Serapi. Satu daripada senjata mereka mengenai pipi Santubong dan gunung itu sumbing, tetapi namanya sudah luntur.", "options": [{"text": "Antan terkena pipi Santubong, lalu Gunung Santubong sumbing.", "isCorrect": true}, {"text": "Batang belidah terkena pipi Santubong, lalu Gunung Santubong sumbing.", "isCorrect": false, "consequence": "Gulung itu ditulis semula dengan senjata yang salah. Cucu-cucu menyangka batang belidah membuat gunung sumbing."}, {"text": "Ayam gergasi merah mengibar sayap dan gunung itu sumbing.", "isCorrect": false, "consequence": "Cerita Nunuk Ragang bercampur dengan Santubong. Cucu-cucu keliru dengan asal usul gunung itu."}], "aftermath": "Gulung cerita disalah baca. Asal usul gunung dan pulau bercampur dengan cerita lain.", "turns": [{"after": 6, "options": [{"text": "Antan terkena pipi Santubong, lalu Gunung Santubong sumbing.", "isCorrect": true, "reaction": "Betul, nenek! Santubong tersenyum sumbing dan cucu-cucu bertepuk tangan."}, {"text": "Batang belidah terkena pipi Santubong, lalu gunung itu sumbing.", "isCorrect": false, "reaction": "Batang belidah terkena kepala Sejinjang, nenek! Santubong menggeleng dan gulung pun bergoyang."}, {"text": "Si Luncai terjun dari Gunung Santubong dengan labu-labunya.", "isCorrect": false, "reaction": "Itu bukan cerita Santubong, nenek! Si Luncai ketawa dari gulung sebelah."}], "clue": "Antan dan batang belidah mengenai dua orang berbeza. Gunung sumbing berpunca daripada pipi Santubong."}]}'),
(413, 'e4_n3_s1', 'Nyahkod Surat Pendaftaran Gelanggang', 'Baca surat lama dan tentukan kaum utama Sabah dan Sarawak yang dinyatakan.', '5', 'Mengenal pasti kepelbagaian kaum di Malaysia.', '{"clueText": "Surat lama menulis: Semenanjung ada Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh dan Serani. Kaum utama Sabah dan Sarawak sudah luntur dan tidak kelihatan, tetapi kaum lain di Sabah dan Sarawak masih tertulis.", "options": [{"text": "Kadazandusun di Sabah dan Iban di Sarawak.", "isCorrect": true}, {"text": "Murut dan Rungus di Sarawak, Kenyah dan Melanau di Sabah.", "isCorrect": false, "consequence": "Surat itu ditulis semula dengan kaum bertukar negeri. Pemain pulang dengan peta kaum yang tersalah."}, {"text": "Chetti dan Serani di Sabah, Sikh dan Siam di Sarawak.", "isCorrect": false, "consequence": "Kaum Semenanjung tersalah letak ke Sabah dan Sarawak. Pendaftaran menjadi kelam-kabut."}], "aftermath": "Surat pendaftaran disalah baca. Pemain tersalah menyebut kaum Sabah dan Sarawak.", "turns": [{"after": 4, "options": [{"text": "Kadazandusun di Sabah dan Iban di Sarawak.", "isCorrect": true, "reaction": "Tepat, tok! Pak Bajau dan Apai bertepuk tangan serentak. Pasukan didaftar!"}, {"text": "Siam dan Sikh di Sabah dan Sarawak.", "isCorrect": false, "reaction": "Mereka di Semenanjung, tok! Borang pun dikoyak kerana tersalah daftar."}, {"text": "Chetti dan Serani di Sabah dan Sarawak.", "isCorrect": false, "reaction": "Mereka di Semenanjung juga, tok! Pasukan diminta mendaftar semula."}], "clue": "Surat lama menyebut Kadazandusun di Sabah dan Iban di Sarawak sebagai kaum utama."}]}'),
(414, 'e4_n3_s2', 'Kuiz Gelanggang Petempatan Dahulu', 'Bantu tok menjawab kuiz tentang petempatan dan kerja kaum di Semenanjung dahulu.', '3', 'Mengenal pasti petempatan dan ekonomi kaum di Semenanjung dahulu.', '{"prompt": "Kuiz gelanggang bertanya kepada kau: padankan kaum dengan petempatan dan kerjanya dahulu. Yang manakah paling betul?", "options": [{"text": "Cina di pekan dan bandar sebagai pelombong dan peniaga; India di ladang dan pinggir bandar.", "isCorrect": true}, {"text": "Cina di kampung sebagai nelayan dan petani; India di pedalaman sebagai pemburu hutan.", "isCorrect": false, "consequence": "Pasukan menjawab dengan tempat dan kerja tertukar. Penonton keliru dan skor pasukan jatuh."}, {"text": "Orang Asli di pekan sebagai peniaga kecil; Melayu di ladang sebagai pekerja pelabuhan dan kedai.", "isCorrect": false, "consequence": "Jawapan bercampur aduk antara kaum. Pemain pulang dengan sejarah yang salah."}], "aftermath": "Kuiz dijawab salah. Pemain keliru tentang petempatan dan kerja setiap kaum.", "turns": [{"after": 4, "options": [{"text": "Orang Asli, dengan kraf tangan, berburu dan hasil hutan.", "isCorrect": true, "reaction": "Tepat, tok! Tok Batin mengangkat tangan dan gelanggang bergema dengan sorakan!"}, {"text": "Orang Cina, sebagai pelombong dan peniaga di bandar.", "isCorrect": false, "reaction": "Itu di pekan dan bandar, tok! Ah Meng ketawa sambil menggeleng."}, {"text": "Orang Melayu, sebagai petani dan nelayan di pantai.", "isCorrect": false, "reaction": "Itu di kampung dan pesisir, tok! Aishah menggaru kepala sambil tersenyum."}], "clue": "Pedalaman ialah rumah Orang Asli, dengan hutan sebagai sumber hidup."}]}'),
(415, 'e4_n3_s3', 'Susun Garis Masa Kaum Sarawak', 'Susun kad garis masa kaum Sarawak daripada zaman dahulu hingga kini.', '1', 'Mengenal pasti petempatan dan ekonomi kaum Sarawak dahulu serta kehidupan bersama kini.', '{"timelineItems": [{"id": 1, "year": "Zaman dahulu", "text": "Bidayuh, Kenyah, Kelabit di pedalaman; Iban dan Bisaya di lembah sungai; Melayu, Melanau, Kedayan di pekan dan bandar", "why": "Setiap kaum menetap di tempat dan kerja sendiri."}, {"id": 2, "year": "Merdeka dan Malaysia", "text": "Selepas merdeka dan pembentukan Malaysia, pemimpin bekerja keras dan rakyat bertoleransi", "why": "Kerja keras pemimpin dan toleransi menyatukan rakyat."}, {"id": 3, "year": "Kini", "text": "Rakyat bekerja bersama dan tinggal dalam satu kawasan perumahan", "why": "Hasilnya, pelbagai kaum hidup sebagai jiran."}], "aftermath": "Garis masa kaum Sarawak tertukar. Pemain menyangka kaum hidup bersama sebelum merdeka.", "turns": [{"after": 4, "options": [{"text": "Dahulu mengikut petempatan, kemudian merdeka dan Malaysia, akhirnya hidup bersama.", "isCorrect": true, "reaction": "Tepat, tok! Jenny menyusun kad satu persatu dan Apai bertepuk tangan!"}, {"text": "Hidup bersama dahulu, baru kemudian kembali kepada petempatan berasingan semula.", "isCorrect": false, "reaction": "Terbalik, tok! Kad garis masa pun berselerak ditiup angin sungai."}, {"text": "Merdeka dan Malaysia dahulu, kemudian kembali kepada petempatan lama semula.", "isCorrect": false, "reaction": "Petempatan lama datang dahulu, tok! Jenny menggeleng dan Apai ketawa."}], "clue": "Garis masa bermula dengan petempatan lama, kemudian merdeka dan Malaysia, kemudian hidup bersama kini."}]}'),
(416, 'e4_n3_s4', 'Pengadil Pentas Lima Kaum', 'Pilih padanan alat muzik dan tarian yang betul bagi setiap pasukan.', '3', 'Mengenal pasti alat muzik dan tarian tradisional pelbagai kaum.', '{"prompt": "Pengadil pentas bertanya kepada kau: padanan manakah yang betul antara kaum, alat muzik dan tariannya?", "options": [{"text": "Sarawak: sape dan ngajat; Sabah: kulintangan dan sumazau; India: veenai dan bharatanatyam.", "isCorrect": true}, {"text": "Sarawak: kulintangan dan sumazau; Sabah: sape dan ngajat; India: gambus dan zapin.", "isCorrect": false, "consequence": "Pentas tertukar. Penari sumazau berdiri di pentas ngajat dan penonton keliru dengan bunyi alat."}, {"text": "Cina: gambus dan zapin; Melayu: gendang dan tarian singa; India: sape dan ngajat.", "isCorrect": false, "consequence": "Alat muzik bertukar antara kaum. Muzik jadi sumbang dan pasukan hilang mata."}], "aftermath": "Padanan alat muzik dan tarian tertukar. Pentas berbunyi sumbang dan penonton keliru.", "turns": [{"after": 4, "options": [{"text": "Sabah.", "isCorrect": true, "reaction": "Tepat, tok! Linda melompat gembira dan gong Sabah berdentum!"}, {"text": "Sarawak.", "isCorrect": false, "reaction": "Sumazau bukan Sarawak, tok! Penari ngajat pun menoleh hairan."}, {"text": "Cina.", "isCorrect": false, "reaction": "Tarian Cina ialah tarian singa, tok! Singa itu menggeleng kepala, hehe."}], "clue": "Sumazau dimainkan dengan kulintangan dan sompotan di Sabah."}]}'),
(417, 'e4_n3_s5', 'Nyahkod Papan Skor Permainan', 'Baca papan skor lama dan tentukan permainan di kawasan lapang.', '5', 'Mengenal pasti permainan tradisional anjung, laman dan kawasan lapang.', '{"clueText": "Papan skor lama menulis: anjung dan laman ada senarai sendiri. Permainan di kawasan lapang sudah luntur, tetapi ia melibatkan angin, tali dan putaran di tanah luas.", "options": [{"text": "Wau, tibau, sepak manggis dan gasing.", "isCorrect": true}, {"text": "Congkak, batu seremban, go dan yoyo cina.", "isCorrect": false, "consequence": "Papan skor menyalin senarai anjung. Kanak-kanak bermain congkak di tengah padang yang luas."}, {"text": "Sepak raga, chap teh dan kabaddi.", "isCorrect": false, "consequence": "Papan skor menyalin senarai laman. Kanak-kanak berkumpul di laman sempit dan padang terbiar."}], "aftermath": "Papan skor disalah baca. Kanak-kanak bermain di tempat yang tidak sesuai.", "turns": [{"after": 4, "options": [{"text": "Wau, tibau, sepak manggis dan gasing.", "isCorrect": true, "reaction": "Tepat, tok! Wau naik ke langit dan gasing menari di tanah!"}, {"text": "Congkak, batu seremban, go dan yoyo cina.", "isCorrect": false, "reaction": "Itu permainan anjung, tok! Congkak pun malu kerana disuruh ke padang."}, {"text": "Sepak raga, chap teh dan kabaddi.", "isCorrect": false, "reaction": "Itu permainan laman, tok! Ah Meng ketawa sambil menyepak raga ke langit."}], "clue": "Papan skor menyebut wau dan gasing ialah permainan yang memerlukan padang luas."}]}'),
(418, 'e4_n3_s6', 'Cari Bukti Legenda Nunuk Ragang', 'Cari bukti legenda Nunuk Ragang pada gambar gelanggang cerita.', '2', 'Memahami cerita rakyat Si Luncai, Legenda Santubong dan Legenda Nunuk Ragang.', '{"bgImage": "../assets/gameAsset/background/nunuk_ragang.png", "hotspots": [{"name": "Pohon nunuk besar tempat penduduk Sungai Liwagu berehat", "top": "25%", "left": "25%"}, {"name": "Rakit di sungai: petempatan awal penduduk di Tambunan dan Ranau", "top": "85%", "left": "82%"}, {"name": "Ayam gergasi merah bertaji emas yang mengibar sayap", "top": "55%", "left": "70%"}], "aftermath": "Bukti legenda tersalah cari. Pemain mencampurkan Nunuk Ragang dengan cerita Si Luncai dan Santubong.", "turns": [{"after": 6, "options": [{"text": "Ayam gergasi merah bertaji emas membawa penduduk terbang.", "isCorrect": true, "reaction": "Tepat, tok! Linda menunjuk ke langit dan sayap ayam gergasi berkilau."}, {"text": "Puteri Santubong menenun di atas Gunung Santubong.", "isCorrect": false, "reaction": "Itu cerita Santubong, tok! Puteri itu melambai dari gambar sebelah."}, {"text": "Si Luncai terjun ke sungai Liwagu dengan labu air.", "isCorrect": false, "reaction": "Itu bukan Nunuk Ragang, tok! Si Luncai ketawa terbahak-bahak."}], "clue": "Nunuk Ragang ialah legenda ayam gergasi merah yang membawa penduduk Sungai Liwagu terbang."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e4_n1_s1', 'hint', 'Kaum di Semenanjung: Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh dan Serani. Sabah dan Sarawak pula ada kaum sendiri.', NULL, NULL),
(401, NULL, 'hint', 'Sabah: Kadazandusun dan kaum lain seperti Murut dan Bajau. Sarawak: Iban dan kaum lain seperti Melanau.', 'Kaum di Malaysia: Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh, Serani, Kadazandusun, Iban; kaum lain di Sabah (Murut, Rungus, Iranun, Bajau) dan di Sarawak (Melayu, Kenyah, Melanau, Bidayuh).', 'Betul! Rentak gendang mengiringi tepukan anak-anak muda yang bersorak.'),
(NULL, 'e4_n1_s2', 'hint', 'Melayu di kampung dan pesisir, Cina di pekan dan bandar, India di ladang dan pinggir bandar, Orang Asli di pedalaman.', NULL, NULL),
(402, NULL, 'hint', 'Pantai dan sungai untuk Melayu, bandar untuk Cina, ladang untuk India, hutan untuk Orang Asli.', 'Dahulu: Melayu di kampung dan pesisir (petani, nelayan, peniaga kecil, perkhidmatan awam); Cina di pekan dan bandar (pelombong, peniaga); India di ladang dan pinggir bandar (pekerja ladang, peniaga kecil, pekerja pelabuhan); Orang Asli di pedalaman (kraf tangan, berburu, hasil hutan).', 'Hebat! Setiap kaum menemui tempat dan kerjanya, dan gendang berbunyi serentak.'),
(NULL, 'e4_n1_s3', 'hint', 'Pedalaman: Bidayuh, Kenyah, Kelabit. Lembah sungai: Iban dan Bisaya. Pekan dan bandar: Melayu, Melanau, Kedayan. Kini semua bekerja bersama.', NULL, NULL),
(403, NULL, 'hint', 'Pekan dan bandar: dagang, perahu dan sagu. Padi bukit pula milik pedalaman.', 'Sarawak dahulu: Bidayuh, Kenyah, Kelabit di pedalaman (padi sawah, padi bukit, hasil hutan); Iban dan Bisaya di lembah sungai (petani); Melayu, Melanau, Kedayan di pekan dan bandar (pedagang, pembuat perahu, pengusaha sagu). Kini semua bekerja bersama.', 'Betul! Nota lama itu terang semula, dan Apai menepuk dayung tanda bangga.'),
(NULL, 'e4_n1_s4', 'hint', 'Melayu: gambus, makyung, zapin. Cina: gendang, tarian singa. India: veenai, bharatanatyam. Sarawak: sape, ngajat. Sabah: kulintangan, sumazau.', NULL, NULL),
(404, NULL, 'hint', 'Cari pentas Melayu, tarian singa, pentas India, penari ngajat dan penari sumazau. Lima kaum, lima rentak.', 'Melayu: angklung, gambus, nafiri, geduk; makyung, zapin. Cina: gendang, bo, liu qin, seruling; tarian singa. India: pullangkulal, talam, mattalam, veenai; bharatanatyam. Sarawak: sape, engkerurai, engkerumong; ngajat. Sabah: kulintangan, sompotan, tongkungan, tontog; sumazau.', 'Hebat! Lima pentas menyala serentak dan padang bergema dengan tepukan.'),
(NULL, 'e4_n1_s5', 'hint', 'Tiga tempat: anjung untuk permainan papan dan batu, laman untuk sepak raga dan chap teh, kawasan lapang untuk wau dan gasing.', NULL, NULL),
(405, NULL, 'hint', 'Papan dan batu di anjung, bola dan kabaddi di laman, wau dan gasing di kawasan lapang.', 'Anjung: congkak, batu seremban, go atau weiqi, yoyo cina atau diabolo, chaturangam, paramapadham. Laman: sepak raga, chap teh, kabaddi. Kawasan lapang: wau, tibau, sepak manggis, gasing.', 'Tepat! Permainan bertemu tempatnya dan kanak-kanak melompat gembira.'),
(NULL, 'e4_n1_s6', 'hint', 'Tiga cerita rakyat: Si Luncai, Santubong dan Nunuk Ragang. Susun tipu helah Si Luncai: guni, perahu, labu, terjun dan campak.', NULL, NULL),
(406, NULL, 'hint', 'Hukuman dahulu, kemudian guni dan perahu, lagu menyebabkan leka, barulah tipu helah dengan labu.', 'Si Luncai: dihukum raja, dimasukkan ke dalam guni, menyanyi sehingga pesuruh raja leka, lalu terjun dengan labu air. Santubong: Puteri Santubong dan Sejinjang bergaduh kerana Putera Serapi, menjadi gunung. Nunuk Ragang: ayam gergasi membawa penduduk membina petempatan dan dialek sendiri.', 'Hebat! Cerita Si Luncai tersusun cantik dan pantai bergema dengan tawa.'),
(NULL, 'e4_n2_s1', 'hint', 'Semenanjung: Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh, Serani. Sabah: Kadazandusun. Sarawak: Iban.', NULL, NULL),
(407, NULL, 'hint', 'Sembilan kad Semenanjung, Kadazandusun dan Iban, kemudian kaum lain di Sabah dan Sarawak.', 'Kaum di Malaysia: Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh, Serani; Kadazandusun (Sabah), Iban (Sarawak); kaum lain di Sabah (Murut, Rungus, Iranun, Bajau) dan Sarawak (Melayu, Kenyah, Melanau, Bidayuh).', 'Hebat! Semua kad tersimpan di laci betul dan peti nenek berkilau.'),
(NULL, 'e4_n2_s2', 'hint', 'Melayu: kampung dan pesisir. Cina: pekan dan bandar. India: ladang dan pinggir bandar. Orang Asli: pedalaman.', NULL, NULL),
(408, NULL, 'hint', 'India: ladang dan pinggir bandar. Kerjanya ladang, niaga kecil dan pelabuhan.', 'Dahulu: Melayu di kampung dan pesisir (petani, nelayan, peniaga kecil, perkhidmatan awam); Cina di pekan dan bandar (pelombong, peniaga); India di ladang dan pinggir bandar (ladang, niaga kecil, pelabuhan); Orang Asli di pedalaman (kraf tangan, berburu, hasil hutan).', 'Betul! Nota lama itu terang semula dan nenek tersenyum bangga.'),
(NULL, 'e4_n2_s3', 'hint', 'Pedalaman: Bidayuh, Kenyah, Kelabit. Lembah sungai: Iban, Bisaya. Pekan dan bandar: Melayu, Melanau, Kedayan.', NULL, NULL),
(409, NULL, 'hint', 'Lembah sungai: Iban dan Bisaya. Kini rakyat tinggal bersama dalam satu kawasan perumahan.', 'Sarawak dahulu: Bidayuh, Kenyah, Kelabit di pedalaman (padi sawah, padi bukit, hasil hutan); Iban dan Bisaya di lembah sungai (petani); Melayu, Melanau, Kedayan di pekan dan bandar (pedagang, pembuat perahu, pengusaha sagu). Kini rakyat bekerja bersama dan tinggal dalam satu kawasan perumahan.', 'Betul! Lukisan lama bercahaya dan nenek mengusap rambut cucu dengan senyum.'),
(NULL, 'e4_n2_s4', 'hint', 'Melayu: gambus dan zapin. Cina: gendang dan tarian singa. India: veenai dan bharatanatyam. Sarawak: sape dan ngajat. Sabah: kulintangan dan sumazau.', NULL, NULL),
(410, NULL, 'hint', 'Lima pentas, lima kaum: Melayu, Cina, India, Sarawak dan Sabah.', 'Melayu: angklung, gambus, nafiri, geduk; makyung, zapin. Cina: gendang, bo, liu qin, seruling; tarian singa. India: pullangkulal, talam, mattalam, veenai; bharatanatyam. Sarawak: sape, engkerurai, engkerumong; ngajat. Sabah: kulintangan, sompotan, tongkungan, tontog; sumazau.', 'Betul! Lima pentas berdentum serentak dan cucu-cucu menari.'),
(NULL, 'e4_n2_s5', 'hint', 'Anjung: congkak, batu seremban, go, yoyo cina, chaturangam, paramapadham. Laman: sepak raga, chap teh, kabaddi. Lapang: wau, tibau, sepak manggis, gasing.', NULL, NULL),
(411, NULL, 'hint', 'Cari congkak di anjung, sepak raga di laman, wau di langit dan gasing di tanah lapang.', 'Anjung: congkak, batu seremban, go atau weiqi, yoyo cina atau diabolo, chaturangam, paramapadham. Laman: sepak raga, chap teh, kabaddi. Kawasan lapang: wau, tibau, sepak manggis, gasing.', 'Hebat! Setiap permainan menemui tempatnya dan padang bergema dengan tawa.'),
(NULL, 'e4_n2_s6', 'hint', 'Si Luncai: guni, labu, perahu. Santubong: dua puteri, antan, gunung sumbing. Nunuk Ragang: ayam gergasi merah bertaji emas.', NULL, NULL),
(412, NULL, 'hint', 'Antan mengenai pipi Santubong. Batang belidah mengenai kepala Sejinjang.', 'Si Luncai: dihukum raja, dimasukkan ke dalam guni di atas perahu, menipu pesuruh raja dengan lagu, mengisi labu dalam guni, terjun dengan labu air. Santubong: antan terkena pipi Santubong, batang belidah terkena kepala Sejinjang menjadi pulau. Nunuk Ragang: ayam gergasi membawa penduduk, petempatan dan dialek sendiri.', 'Betul! Gulung itu terang semula dan nenek menutup peti dengan senyuman.'),
(NULL, 'e4_n3_s1', 'hint', 'Semenanjung: Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh, Serani. Sabah dan Sarawak ada kaum sendiri.', NULL, NULL),
(413, NULL, 'hint', 'Sabah: Kadazandusun. Sarawak: Iban. Kaum lain di Sabah: Murut, Rungus, Iranun, Bajau. Sarawak: Melayu, Kenyah, Melanau, Bidayuh.', 'Kaum di Malaysia: Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh, Serani; Kadazandusun, Iban; kaum lain di Sabah (Murut, Rungus, Iranun, Bajau) dan Sarawak (Melayu, Kenyah, Melanau, Bidayuh).', 'Betul! Surat itu terang semula dan wisel tok berbunyi riang.'),
(NULL, 'e4_n3_s2', 'hint', 'Melayu: kampung dan pesisir. Cina: pekan dan bandar. India: ladang dan pinggir bandar. Orang Asli: pedalaman.', NULL, NULL),
(414, NULL, 'hint', 'Cina di bandar, India di ladang, Melayu di kampung, Orang Asli di pedalaman.', 'Dahulu: Melayu di kampung dan pesisir (petani, nelayan, peniaga kecil, perkhidmatan awam); Cina di pekan dan bandar (pelombong, peniaga); India di ladang dan pinggir bandar (ladang, peniaga kecil, pelabuhan); Orang Asli di pedalaman (kraf tangan, berburu, hasil hutan).', 'Betul! Skor melonjak dan tok meniup wisel kemenangan.'),
(NULL, 'e4_n3_s3', 'hint', 'Pedalaman: Bidayuh, Kenyah, Kelabit. Lembah sungai: Iban, Bisaya. Pekan dan bandar: Melayu, Melanau, Kedayan. Kini semua bekerja bersama.', NULL, NULL),
(415, NULL, 'hint', 'Petempatan lama dahulu, kemudian merdeka dan Malaysia, akhirnya kini hidup bersama.', 'Sarawak dahulu: Bidayuh, Kenyah, Kelabit di pedalaman (padi sawah, padi bukit, hasil hutan); Iban dan Bisaya di lembah sungai (petani); Melayu, Melanau, Kedayan di pekan dan bandar (pedagang, pembuat perahu, pengusaha sagu). Kini rakyat bekerja bersama dan tinggal dalam satu kawasan perumahan.', 'Betul! Garis masa tersusun cantik dan gelanggang bersorak.'),
(NULL, 'e4_n3_s4', 'hint', 'Melayu: gambus, zapin. Cina: gendang, tarian singa. India: veenai, bharatanatyam. Sarawak: sape, ngajat. Sabah: kulintangan, sumazau.', NULL, NULL),
(416, NULL, 'hint', 'Sape dan ngajat di Sarawak, kulintangan dan sumazau di Sabah, veenai dan bharatanatyam bagi India.', 'Melayu: angklung, gambus, nafiri, geduk; makyung, zapin. Cina: gendang, bo, liu qin, seruling; tarian singa. India: pullangkulal, talam, mattalam, veenai; bharatanatyam. Sarawak: sape, engkerurai, engkerumong; ngajat. Sabah: kulintangan, sompotan, tongkungan, tontog; sumazau.', 'Betul! Lima pentas menyala dan pengadil mengangkat bendera hijau.'),
(NULL, 'e4_n3_s5', 'hint', 'Anjung: congkak, batu seremban, go, yoyo cina, chaturangam, paramapadham. Laman: sepak raga, chap teh, kabaddi. Lapang: wau, tibau, sepak manggis, gasing.', NULL, NULL),
(417, NULL, 'hint', 'Wau dan gasing perlukan tanah luas. Congkak untuk anjung, sepak raga untuk laman.', 'Anjung: congkak, batu seremban, go atau weiqi, yoyo cina atau diabolo, chaturangam, paramapadham. Laman: sepak raga, chap teh, kabaddi. Kawasan lapang: wau, tibau, sepak manggis, gasing.', 'Betul! Papan skor terang semula dan padang gamat dengan tawa.'),
(NULL, 'e4_n3_s6', 'hint', 'Si Luncai: guni dan labu. Santubong: antan dan batang belidah. Nunuk Ragang: pohon nunuk dan ayam gergasi merah bertaji emas.', NULL, NULL),
(418, NULL, 'hint', 'Cari pohon nunuk, rakit di sungai dan ayam gergasi yang mengibar sayap.', 'Si Luncai: dihukum raja, guni di atas perahu, lagu menipu pesuruh raja, labu air. Santubong: antan terkena pipi Santubong, batang belidah terkena kepala Sejinjang. Nunuk Ragang: ayam gergasi merah bertaji emas membawa penduduk Sungai Liwagu, petempatan Tambunan dan Ranau, dialek sendiri.', 'Hebat! Tiga bukti ditemui dan gelanggang cerita bergema dengan tepukan.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(61, 401, NULL, 'Tugasku ialah membawa rentak setiap kaum ke satu pentas supaya setiap bunyi dihargai. Jika pemuzik berhenti, lagu warisan itu hilang bersama orang tua, {nama}.', 1),
(61, 401, NULL, 'Setiap kaum membawa rentak sendiri, dan lagu Malaysia hanya merdu apabila semua rentak dimainkan bersama.', 2),
(61, 401, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemuzik tua yang membawa gambus, sape dan gendang dari kampung ke kampung. Rentak sudah bermula, jangan terlepas ketukan!', 3),
(69, 401, 'e4_n1_s1', 'Pak Cik! Ah Meng lapor diri! Pentas penuh sesak dan setiap kaum bawa rentak sendiri. Tapi kami keliru: berapa banyak kaum sebenarnya? Misi hari ini: kenal semua!', 1),
(NULL, 401, 'e4_n1_s1', 'TUNG-TUNG-TUNG! Mulakan dengan Semenanjung: Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh dan Serani. Banyaknya, macam senarai lagu!', 2),
(66, 401, 'e4_n1_s1', 'Linda dari Sabah pula, pak cik! Kami ada Kadazandusun, dan kaum lain seperti Murut, Rungus, Iranun dan Bajau.', 3),
(67, 401, 'e4_n1_s1', 'Jenny dari Sarawak! Kami ada Iban, dan kaum lain seperti Melayu, Kenyah, Melanau dan Bidayuh. Pak cik, kaum yang manakah termasuk kaum lain di Sabah?', 4),
(64, 401, 'e4_n1_s2', 'Pak Cik Pemuzik! Aishah di sini. Kampung kami di tepi pantai dan sungai. Ayah saya petani dan nelayan, emak berniaga kecil-kecilan. Ada juga yang makan gaji kerajaan!', 1),
(69, 401, 'e4_n1_s2', 'Kalau saya, pak cik, keluarga Ah Meng di pekan dan bandar. Datuk melombong, ayah berniaga. Pekan pun bising dengan ''KLANG-KLANG'' dari kedai!', 2),
(65, 401, 'e4_n1_s2', 'Kavitha pula tinggal di ladang dan pinggir bandar, pak cik. Ayah bekerja di ladang, ada juga yang jadi peniaga kecil dan pekerja pelabuhan.', 3),
(70, 401, 'e4_n1_s2', 'Dan kami Orang Asli, anak. Kami di pedalaman, membuat kraf tangan, berburu dan memungut hasil hutan. Pak Cik, kaum yang manakah tinggal di pekan dan bandar, dan kerja mereka apa?', 4),
(68, 401, 'e4_n1_s3', 'Selamat datang, pemuzik! Apai ini orang Iban, kami di lembah sungai dan bertani. Dayung perlahan, nanti perahu kita ikut rentak sape!', 1),
(67, 401, 'e4_n1_s3', 'Jenny tolong cerita, pak cik. Kaum Bidayuh, Kenyah dan Kelabit di pedalaman. Mereka tanam padi sawah dan padi bukit, juga mengutip hasil hutan.', 2),
(NULL, 401, 'e4_n1_s3', 'Wah! Dan di pekan dan bandar pula Melayu, Melanau dan Kedayan. Mereka pedagang, pembuat perahu dan pengusaha sagu. Iban dan Bisaya di lembah sungai, bertani.', 3),
(68, 401, 'e4_n1_s3', 'Kini, selepas merdeka dan pembentukan Malaysia, hasil kerja keras pemimpin dan sikap toleransi, semua kaum bekerja bersama dan tinggal dalam satu kawasan perumahan. Pak Cik, nyahkod nota lama ini!', 4),
(65, 401, 'e4_n1_s4', 'Pak Cik! Kavitha lapor diri! Pentas India saya baru siap. Veenai, mattalam dan talam sudah sedia, dan tarian bharatanatyam akan bermula, TING-TING!', 1),
(69, 401, 'e4_n1_s4', 'Hampir, pak cik! Pentas Cina ada gendang, bo, liu qin dan seruling. Tarian singa mesti menari dahulu, nanti singa merajuk!', 2),
(NULL, 401, 'e4_n1_s4', 'Melayu pula: angklung, gambus, nafiri dan geduk, dengan tarian makyung dan zapin. Sarawak: sape, engkerurai, engkerumong dengan tarian ngajat. Sabah: kulintangan, sompotan, tongkungan, tontog dengan tarian sumazau.', 3),
(66, 401, 'e4_n1_s4', 'Wah! Pak cik, tarian sumazau itu dari pentas kaum yang manakah?', 4),
(74, 401, 'e4_n1_s5', 'Pak Cik! Cikgu kata ada tiga jenis tempat permainan tradisional: anjung, laman dan kawasan lapang. Apa dalam setiap satu? Saya hendak menang pertandingan!', 1),
(NULL, 401, 'e4_n1_s5', 'Anjung dahulu, ya: congkak, batu seremban, go atau weiqi, yoyo cina atau diabolo, chaturangam dan paramapadham. Rentak perlahan, macam duduk bersila.', 2),
(69, 401, 'e4_n1_s5', 'Laman pula, pak cik? Sepak raga, chap teh dan kabaddi! Ah Meng sudah pecah peluh, hehe.', 3),
(NULL, 401, 'e4_n1_s5', 'Dan kawasan lapang: wau, tibau, sepak manggis dan gasing. Wau terbang tinggi, gasing berpusing laju.', 4),
(74, 401, 'e4_n1_s5', 'Hebat! Pak Cik, jika saya mahu bermain wau, di manakah tempat yang paling sesuai?', 5),
(72, 401, 'e4_n1_s6', 'Hehe, pemuzik! Aku Si Luncai! Raja menghukum aku kerana mempermain-mainkan baginda dan pembesar. Mereka masukkan aku ke dalam guni, letak atas perahu ke tengah laut! GLUP-GLUP!', 1),
(NULL, 401, 'e4_n1_s6', 'Wah, Luncai! Kau menipu pesuruh raja dengan lagu: ''Si Luncai terjun dengan labu-labunya. Biarkan! Biarkan!'' Mereka pun leka menyanyi, hehe!', 2),
(73, 401, 'e4_n1_s6', 'Aku Puteri Santubong, pemuzik. Aku menenun, Puteri Sejinjang menumbuk padi. Kami diturunkan dari kayangan untuk mendamaikan kampung Pasir Kuning dan Pasir Putih.', 3),
(73, 401, 'e4_n1_s6', 'Tapi kami berebut Putera Serapi dari Matang lalu bertelingkah. Antan terkena pipiku, Gunung Santubong sumbing. Batang belidah terkena kepala Sejinjang, lalu jadi Pulau Kera, Satang dan Talang-talang.', 4),
(66, 401, 'e4_n1_s6', 'Nunuk Ragang pula cerita Sabah, pak cik! Penduduk Sungai Liwagu berehat di bawah pohon nunuk. Ayam gergasi merah bertaji emas membawa mereka terbang. Di mana sayap dikibar, di situ mereka jatuh.', 5),
(66, 401, 'e4_n1_s6', 'Di situ mereka membina petempatan di Tambunan dan Ranau. Mereka terpisah lalu membina dialek masing-masing. Itulah asal pelbagai kaum di sana!', 6),
(72, 401, 'e4_n1_s6', 'Eh, pemuzik! Tolong susun tipu helahku. Apa yang aku buat apabila pesuruh raja leka menyanyi?', 7),
(62, 402, NULL, 'Tugasku ialah menurunkan cerita kaum supaya cucu mengenali jiran sendiri. Jika nenek berdiam diri, cerita itu hilang bersama usia, {nama}.', 1),
(62, 402, NULL, 'Cerita setiap kaum ialah satu laci dalam peti yang sama, dan Malaysia lengkap apabila semua laci dibuka dan dikongsi.', 2),
(62, 402, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, nenek yang menyimpan cerita semua kaum dalam peti lamanya. Cucu-cucu sudah duduk bersila, bukalah laci pertama!', 3),
(74, 402, 'e4_n2_s1', 'Nenek! Nenek! Peti itu berkunci, tapi cikgu kata Malaysia ada banyak kaum! Berapa banyak, nenek? Kami mahu kad bergambar!', 1),
(NULL, 402, 'e4_n2_s1', 'Sabarlah, cucu! Laci pertama: Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh dan Serani. Sembilan kad untuk Semenanjung!', 2),
(66, 402, 'e4_n2_s1', 'Nek, di Sabah ada Kadazandusun! Jiran saya Pak Bajau, jadi Bajau pun ada. Murut, Rungus dan Iranun juga kaum di Sabah!', 3),
(67, 402, 'e4_n2_s1', 'Di Sarawak ada Iban, nek! Kawan saya orang Melayu, Kenyah, Melanau dan Bidayuh. Semua kaum Sarawak!', 4),
(74, 402, 'e4_n2_s1', 'Hebat! Nenek, sekarang kami mahu padankan kad. Apakah kaum lain di Sabah dalam senarai nenek tadi?', 5),
(64, 402, 'e4_n2_s2', 'Nenek! Aishah mahu tahu. Datuk kata kami orang Melayu dahulu tinggal di kampung, persisiran pantai dan sungai. Nenek, apa kerja kami?', 1),
(NULL, 402, 'e4_n2_s2', 'Petani, nelayan dan peniaga kecil-kecilan, cu. Ada juga yang berkhidmat dalam perkhidmatan awam. Bau laut dan bau padi bercampur, sedap!', 2),
(69, 402, 'e4_n2_s2', 'Nenek! Ah Meng pula? Datuk saya tinggal di pekan dan bandar. Dia pelombong, kemudian berniaga. Kedai kami bising dengan KLANG-KLANG timbangan!', 3),
(65, 402, 'e4_n2_s2', 'Kavitha di ladang dan pinggir bandar, nek! Bapa bekerja di ladang, ada yang berniaga kecil dan bekerja di pelabuhan.', 4),
(70, 402, 'e4_n2_s2', 'Kami Orang Asli di pedalaman. Kraf tangan, berburu dan memungut hasil hutan. Nenek, baca nota lama ini dahulu sebelum kami pulang ke hutan!', 5),
(67, 402, 'e4_n2_s3', 'Nenek, Jenny pula! Kaum Bidayuh, Kenyah dan Kelabit tinggal di pedalaman. Mereka tanam padi sawah dan padi bukit, juga kutip hasil hutan!', 1),
(68, 402, 'e4_n2_s3', 'Apai Iban beritahu. Iban dan Bisaya di lembah sungai, kami petani. Air sungai jadi jalan kami!', 2),
(NULL, 402, 'e4_n2_s3', 'Dan di pekan dan bandar: Melayu, Melanau dan Kedayan. Mereka pedagang, pembuat perahu dan pengusaha sagu. Pandai sungguh, macam kilang kecil!', 3),
(67, 402, 'e4_n2_s3', 'Kini, nek? Kata cikgu, selepas merdeka dan pembentukan Malaysia, hasil kerja keras pemimpin dan sikap toleransi, rakyat bekerja bersama dan tinggal dalam satu kawasan perumahan!', 4),
(68, 402, 'e4_n2_s3', 'Betul, nenek. Sekarang rumah jiran saya Cina, India, Melayu. Nenek, kaum manakah di lembah sungai dan apa kerjanya?', 5),
(65, 402, 'e4_n2_s4', 'Nenek, Kavitha mahu menari bharatanatyam! Iringannya pullangkulal, talam, mattalam dan veenai. TING-TING-TING!', 1),
(69, 402, 'e4_n2_s4', 'Ah Meng pun mahu, nek! Cina ada gendang, bo, liu qin dan seruling, dengan tarian singa. Singa saya pandai kenyit mata!', 2),
(NULL, 402, 'e4_n2_s4', 'Melayu: angklung, gambus, nafiri dan geduk, dengan makyung dan zapin. Sarawak: sape, engkerurai, engkerumong dengan ngajat. Sabah: kulintangan, sompotan, tongkungan, tontog dengan sumazau.', 3),
(66, 402, 'e4_n2_s4', 'Nek, alat muzik sumazau di pentas Sabah ada sompotan dan kulintangan, kan? Nenek, padankan lima kaum dengan tarian mereka!', 4),
(74, 402, 'e4_n2_s5', 'Nenek! Nenek! Dulu nenek main apa? Kami mahu main yang nenek main, tapi mesti betul tempatnya!', 1),
(NULL, 402, 'e4_n2_s5', 'Di anjung: congkak, batu seremban, go atau weiqi, yoyo cina atau diabolo, chaturangam dan paramapadham. Main sambil minum teh, hehe!', 2),
(69, 402, 'e4_n2_s5', 'Di laman: sepak raga, chap teh dan kabaddi! Ah Meng jaguh kabaddi, tak ada siapa boleh tangkap!', 3),
(63, 402, 'e4_n2_s5', 'Di kawasan lapang: wau, tibau, sepak manggis dan gasing. Tok Permainan datang, nek! Cuba cari permainan pada gambar padang ini!', 4),
(72, 402, 'e4_n2_s6', 'Hehe, nenek! Aku Si Luncai, dihukum raja kerana mempermain-mainkan baginda. Aku dimasukkan dalam guni di atas perahu. Aku tipu pesuruh raja dengan lagu: ''Si Luncai terjun dengan labu-labunya, biarkan! biarkan!''', 1),
(72, 402, 'e4_n2_s6', 'Mereka leka menyanyi. Aku isi labu dalam guni, terjun dan berenang dengan labu air. Guni berisi labu itu mereka campak ke laut. Gempak, kan?', 2),
(73, 402, 'e4_n2_s6', 'Aku Puteri Santubong, menenun. Sejinjang menumbuk padi. Kami turun dari kayangan untuk mendamaikan Pasir Kuning dan Pasir Putih. Tetapi kami menyukai Putera Serapi dari Matang lalu bertelingkah.', 3),
(73, 402, 'e4_n2_s6', 'Antan terkena pipiku, Gunung Santubong sumbing. Batang belidah terkena kepala Sejinjang, lalu menjadi Pulau Kera, Pulau Satang dan Pulau Talang-talang.', 4),
(66, 402, 'e4_n2_s6', 'Nunuk Ragang, nek! Penduduk Sungai Liwagu berehat di bawah pohon nunuk. Ayam gergasi merah bertaji emas membawa mereka terbang. Di mana sayap dikibar, di situ mereka jatuh dan bina petempatan di Tambunan dan Ranau.', 5),
(66, 402, 'e4_n2_s6', 'Mereka terpisah dan membina dialek masing-masing. Nenek, baca teka-teki pada gulung Santubong ini!', 6),
(63, 403, NULL, 'Tugasku ialah memastikan semua kaum bermain di gelanggang yang sama supaya warisan tidak padam. Jika gelanggang sunyi, permainan lama pun hilang, {nama}.', 1),
(63, 403, NULL, 'Setiap kaum membawa permainan, muzik dan cerita sendiri ke gelanggang, dan Malaysia menang apabila semua bermain bersama.', 2),
(63, 403, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penjaga gelanggang tempat semua kaum bermain bersama. Wisel sudah ditiup, pusingan pertama bermula!', 3),
(69, 403, 'e4_n3_s1', 'Tok! Ah Meng daftar pasukan! Borang tanya kaum apa sahaja boleh masuk. Cepat, wisel tok sudah berbunyi, PEEEP!', 1),
(NULL, 403, 'e4_n3_s1', 'Semenanjung masuk dahulu: Melayu, Cina, India, Siam, Orang Asli, Chetti, Baba dan Nyonya, Sikh dan Serani. Sembilan pasukan, gelanggang pun penuh!', 2),
(71, 403, 'e4_n3_s1', 'Pak Bajau dari Sabah daftar, tok! Kadazandusun pun ada. Kami dari Murut, Rungus, Iranun dan Bajau juga main sama.', 3),
(68, 403, 'e4_n3_s1', 'Apai dari Sarawak, tok! Iban dan kaum lain seperti Melayu, Kenyah, Melanau dan Bidayuh ikut sama. Tok, ada surat lama pasal pendaftaran ini!', 4),
(70, 403, 'e4_n3_s2', 'Tok Batin dari pedalaman! Kami buat kraf tangan, berburu dan memungut hasil hutan. Gelanggang kuiz tok, mari mulakan!', 1),
(64, 403, 'e4_n3_s2', 'Aishah dari kampung, persisiran pantai dan sungai! Ayah kami petani dan nelayan, ada peniaga kecil-kecilan dan ada makan gaji perkhidmatan awam!', 2),
(69, 403, 'e4_n3_s2', 'Ah Meng dari pekan dan bandar! Datuk saya pelombong, ayah peniaga. Kedai kami KLING-KLING siang malam!', 3),
(65, 403, 'e4_n3_s2', 'Kavitha dari ladang dan pinggir bandar! Kami bekerja di ladang, ada peniaga kecil dan pekerja pelabuhan. Tok, soalan mata penentu: siapa tinggal di pedalaman?', 4),
(67, 403, 'e4_n3_s3', 'Tok, Jenny bawa kad garis masa! Kaum Bidayuh, Kenyah dan Kelabit di pedalaman, tanam padi sawah dan padi bukit, juga mengutip hasil hutan.', 1),
(68, 403, 'e4_n3_s3', 'Apai di lembah sungai, tok. Iban dan Bisaya bertani, air sungai jadi gelanggang kami!', 2),
(NULL, 403, 'e4_n3_s3', 'Di pekan dan bandar pula Melayu, Melanau dan Kedayan: pedagang, pembuat perahu dan pengusaha sagu. Hebat semuanya!', 3),
(67, 403, 'e4_n3_s3', 'Selepas merdeka dan pembentukan Malaysia, hasil kerja keras pemimpin dan sikap toleransi, rakyat bekerja bersama dan tinggal dalam satu kawasan perumahan. Tok, tolong susun garis masa kami!', 4),
(69, 403, 'e4_n3_s4', 'Tok, pasukan Cina bertanding! Gendang, bo, liu qin dan seruling, dengan tarian singa. DUM-DUM-DUM!', 1),
(65, 403, 'e4_n3_s4', 'India pula tok! Pullangkulal, talam, mattalam dan veenai, dengan bharatanatyam. Kavitha menari dahulu!', 2),
(NULL, 403, 'e4_n3_s4', 'Melayu: angklung, gambus, nafiri dan geduk, dengan makyung dan zapin. Sarawak: sape, engkerurai, engkerumong, ngajat. Sabah: kulintangan, sompotan, tongkungan, tontog, sumazau.', 3),
(66, 403, 'e4_n3_s4', 'Linda bersedia, tok! Satu soalan: tarian sumazau milik kaum yang mana?', 4),
(74, 403, 'e4_n3_s5', 'Tok, saya mahu main semua! Tapi papan skor luntur. Tok bacalah, sebelum kita mula!', 1),
(NULL, 403, 'e4_n3_s5', 'Anjung: congkak, batu seremban, go atau weiqi, yoyo cina atau diabolo, chaturangam dan paramapadham. Laman: sepak raga, chap teh dan kabaddi.', 2),
(NULL, 403, 'e4_n3_s5', 'Kawasan lapang: wau, tibau, sepak manggis dan gasing. Semua kaum main bersama di sini!', 3),
(69, 403, 'e4_n3_s5', 'Tok, baca papan skor ini dahulu: permainan manakah di kawasan lapang?', 4),
(72, 403, 'e4_n3_s6', 'Hehe, tok! Si Luncai dihukum raja kerana mempermain-mainkan baginda dan pembesar. Aku dimasukkan dalam guni atas perahu. Aku tipu pesuruh raja dengan lagu: ''Si Luncai terjun dengan labu-labunya, biarkan! biarkan!''', 1),
(72, 403, 'e4_n3_s6', 'Mereka leka. Aku isi labu dalam guni, terjun dan berenang dengan labu air. Mereka campak guni berisi labu itu. Aku selamat!', 2),
(73, 403, 'e4_n3_s6', 'Aku Puteri Santubong, menenun. Sejinjang menumbuk padi. Kami diturunkan dari kayangan untuk mendamaikan Pasir Kuning dan Pasir Putih, tapi bertelingkah kerana Putera Serapi dari Matang.', 3),
(73, 403, 'e4_n3_s6', 'Antan terkena pipiku, Gunung Santubong sumbing. Batang belidah terkena kepala Sejinjang lalu menjadi Pulau Kera, Satang dan Talang-talang.', 4),
(66, 403, 'e4_n3_s6', 'Nunuk Ragang pula, tok! Penduduk Sungai Liwagu berehat di bawah pohon nunuk. Ayam gergasi merah bertaji emas membawa mereka terbang. Di mana sayap dikibar, di situ mereka membina petempatan di Tambunan dan Ranau.', 5),
(66, 403, 'e4_n3_s6', 'Mereka terpisah dan membina dialek masing-masing. Tok, cari bukti legenda ini pada gambar!', 6);
INSERT INTO QuestionBank (bankID, eraID) VALUES (4, 4)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(401, 4, 'Antara berikut, yang manakah kaum di Semenanjung Malaysia?', 'Murut', 'Siam', 'Kenyah', 'Rungus', 'B', 'Pilih kaum yang tinggal di Semenanjung.', 'Siam ialah salah satu kaum di Semenanjung, bersama Melayu, Cina, India dan Orang Asli.'),
(402, 4, 'Kaum manakah termasuk dalam kaum peranakan atau kecil di Semenanjung?', 'Bidayuh dan Kenyah', 'Murut dan Rungus', 'Iban dan Melanau', 'Baba dan Nyonya', 'D', 'Kaum ini bercampur budaya Cina dan tempatan.', 'Baba dan Nyonya, bersama Chetti, Sikh dan Serani, ialah kaum di Semenanjung.'),
(403, 4, 'Kaum manakah termasuk kaum lain di Sabah?', 'Kenyah', 'Rungus', 'Melanau', 'Bidayuh', 'B', 'Ingat empat nama selepas Kadazandusun.', 'Kaum lain di Sabah ialah Murut, Rungus, Iranun dan Bajau.'),
(404, 4, 'Kaum manakah termasuk kaum lain di Sarawak?', 'Iranun', 'Bajau', 'Murut', 'Melanau', 'D', 'Ingat empat nama selain Iban.', 'Kaum lain di Sarawak ialah Melayu, Kenyah, Melanau dan Bidayuh.'),
(405, 4, 'Kadazandusun ialah kaum utama di negeri mana?', 'Sabah', 'Sarawak', 'Kelantan', 'Pahang', 'A', 'Negeri di Pulau Borneo, bukan Sarawak.', 'Kadazandusun ialah kaum yang terkenal di Sabah.'),
(406, 4, 'Iban ialah kaum utama di negeri mana?', 'Sabah', 'Pulau Pinang', 'Sarawak', 'Selangor', 'C', 'Negeri di Pulau Borneo, bukan Sabah.', 'Iban ialah kaum utama di Sarawak.'),
(407, 4, 'Apakah perbezaan kaum lain di Sabah dengan kaum lain di Sarawak?', 'Sabah ada Murut dan Bajau, Sarawak ada Kenyah dan Bidayuh', 'Sabah ada Kenyah dan Bidayuh, Sarawak ada Murut dan Bajau', 'Sabah ada Siam dan Sikh, Sarawak ada Chetti dan Serani', 'Sabah dan Sarawak ada kaum lain yang sama sahaja', 'A', 'Ingat dua kumpulan kaum lain yang berbeza.', 'Kaum lain di Sabah ialah Murut, Rungus, Iranun dan Bajau; di Sarawak ialah Melayu, Kenyah, Melanau dan Bidayuh.'),
(408, 4, 'Apakah ciri kepelbagaian kaum di Malaysia?', 'Hanya satu kaum di setiap negeri kita', 'Hanya kaum Melayu dan Cina di negara', 'Banyak kaum di Semenanjung, Sabah dan Sarawak', 'Kaum hanya wujud di Semenanjung sahaja', 'C', 'Fikirkan semua kawasan Malaysia.', 'Malaysia ada pelbagai kaum di Semenanjung, Sabah dan Sarawak.'),
(409, 4, 'Petempatan orang Melayu dahulu terletak di mana?', 'Kampung, pantai dan sungai', 'Pekan dan bandar yang sibuk', 'Ladang getah dan pinggir bandar', 'Pedalaman yang jauh dari pantai', 'A', 'Dekat air pantai dan sungai.', 'Orang Melayu dahulu menetap di kampung, persisiran pantai dan sungai.'),
(410, 4, 'Apakah kegiatan ekonomi orang Melayu dahulu?', 'Petani, nelayan dan peniaga kecil', 'Pelombong bijih dan peniaga besar', 'Pekerja ladang dan pelabuhan sahaja', 'Pemburu dan pemungut hasil hutan', 'A', 'Dekat laut dan sawah.', 'Orang Melayu dahulu menjadi petani, nelayan, peniaga kecil-kecilan dan bekerja dalam perkhidmatan awam.'),
(411, 4, 'Di mana orang Cina dahulu menetap?', 'Kampung dan persisiran pantai', 'Ladang dan pinggir bandar', 'Pedalaman hutan', 'Pekan dan bandar', 'D', 'Tempat yang berniaga dan melombong.', 'Orang Cina dahulu menetap di pekan dan bandar, kerja sebagai pelombong dan peniaga.'),
(412, 4, 'Apakah kerja orang Cina dahulu?', 'Petani dan nelayan', 'Pekerja ladang dan pelabuhan', 'Pelombong dan peniaga', 'Pemburu dan pengutip hasil hutan', 'C', 'Berkait dengan bijih dan kedai.', 'Orang Cina dahulu bekerja sebagai pelombong dan peniaga di pekan dan bandar.'),
(413, 4, 'Di mana orang India dahulu menetap?', 'Pekan dan bandar besar sahaja', 'Kampung dan pantai yang jauh', 'Ladang dan pinggir bandar', 'Pedalaman hutan Semenanjung kita', 'C', 'Dekat tempat kerja ladang.', 'Orang India dahulu menetap di ladang dan pinggir bandar.'),
(414, 4, 'Apakah kerja orang India dahulu selain bekerja di ladang?', 'Peniaga kecil dan pekerja pelabuhan', 'Pelombong bijih timah di lombong', 'Nelayan di persisiran pantai lama', 'Pemburu di dalam hutan pedalaman', 'A', 'Berkait dengan perniagaan kecil dan pelabuhan.', 'Orang India dahulu bekerja di ladang, berniaga kecil-kecilan dan bekerja di pelabuhan.'),
(415, 4, 'Apakah kegiatan Orang Asli di pedalaman dahulu?', 'Melombong bijih dan berniaga di bandar', 'Bekerja di ladang dan di pelabuhan', 'Menangkap ikan dan menanam padi sawah', 'Kraf tangan, berburu dan hasil hutan', 'D', 'Hutan menjadi sumber hidup.', 'Orang Asli di pedalaman membuat kraf tangan, berburu dan memungut hasil hutan.'),
(416, 4, 'Di mana Bidayuh, Kenyah dan Kelabit menetap?', 'Pedalaman', 'Lembah sungai', 'Pekan dan bandar', 'Pesisiran pantai', 'A', 'Jauh dari sungai besar dan bandar.', 'Bidayuh, Kenyah dan Kelabit menetap di pedalaman Sarawak.'),
(417, 4, 'Apakah ekonomi Bidayuh, Kenyah dan Kelabit dahulu?', 'Berdagang, membuat perahu dan mengusahakan sagu', 'Bertani di lembah sungai dan menangkap ikan', 'Padi sawah, padi bukit dan hasil hutan', 'Bekerja di ladang getah dan di pelabuhan', 'C', 'Tanaman padi dan hutan.', 'Mereka menanam padi sawah dan padi bukit serta mengutip hasil hutan.'),
(418, 4, 'Kaum manakah menetap di lembah sungai Sarawak?', 'Bidayuh dan Kenyah', 'Melayu dan Melanau', 'Kelabit dan Kedayan', 'Iban dan Bisaya', 'D', 'Tinggal di tepi sungai.', 'Iban dan Bisaya menetap di lembah sungai dan menjadi petani.'),
(419, 4, 'Kaum manakah menetap di pekan dan bandar Sarawak?', 'Iban, Bisaya dan Bidayuh', 'Melayu, Melanau dan Kedayan', 'Kenyah, Kelabit dan Iban', 'Bidayuh, Kelabit dan Bisaya', 'B', 'Tiga kaum yang berdagang.', 'Melayu, Melanau dan Kedayan menetap di pekan dan bandar Sarawak.'),
(420, 4, 'Apakah kegiatan ekonomi Melayu, Melanau dan Kedayan di Sarawak dahulu?', 'Berdagang, membuat perahu dan mengusahakan sagu', 'Menanam padi bukit di pedalaman hutan sahaja', 'Mengutip hasil hutan di pedalaman yang jauh', 'Melombong bijih dan berniaga di bandar besar', 'A', 'Berkait dengan dagang, perahu dan sagu.', 'Mereka menjadi pedagang, pembuat perahu dan pengusaha sagu.'),
(421, 4, 'Apakah yang membolehkan rakyat bekerja bersama dan tinggal dalam satu kawasan perumahan kini?', 'Pemisahan kaum mengikut tempat tinggal', 'Kerja keras pemimpin dan toleransi', 'Kegiatan ekonomi yang sama bagi semua', 'Perbezaan bahasa yang besar antara kaum', 'B', 'Hasil kerja pemimpin dan sikap rakyat.', 'Setelah merdeka dan Malaysia terbentuk, kerja keras pemimpin dan toleransi membolehkan rakyat bekerja bersama.'),
(422, 4, 'Apakah keadaan rakyat berbilang kaum kini?', 'Tinggal di tempat berasingan mengikut kaum', 'Bekerja bersama dan satu kawasan perumahan', 'Bekerja hanya dengan kaum sendiri sahaja', 'Menetap hanya di pedalaman hutan jauh', 'B', 'Ingat maksud perkataan kini.', 'Kini rakyat pelbagai kaum mampu bekerja bersama dan tinggal dalam satu kawasan perumahan.'),
(423, 4, 'Alat muzik manakah ialah alat muzik tradisional Melayu?', 'Gambus', 'Veenai', 'Sape', 'Kulintangan', 'A', 'Alat petik Melayu.', 'Alat muzik Melayu termasuk angklung, gambus, nafiri dan geduk.'),
(424, 4, 'Tarian manakah ialah tarian tradisional Melayu?', 'Zapin', 'Ngajat', 'Sumazau', 'Tarian singa', 'A', 'Tarian berpasangan Melayu.', 'Tarian Melayu termasuk makyung dan zapin.'),
(425, 4, 'Alat muzik manakah digunakan dalam muzik tradisional Cina?', 'Mattalam', 'Liu qin', 'Engkerurai', 'Sompotan', 'B', 'Alat tali Cina.', 'Alat muzik Cina termasuk gendang, bo, liu qin dan seruling.'),
(426, 4, 'Apakah tarian tradisional kaum Cina?', 'Bharatanatyam', 'Tarian singa', 'Makyung', 'Ngajat', 'B', 'Menggunakan kostum singa.', 'Tarian tradisional kaum Cina ialah tarian singa.'),
(427, 4, 'Alat muzik manakah digunakan dalam muzik tradisional India?', 'Geduk', 'Kulintangan', 'Bo', 'Veenai', 'D', 'Alat petik India.', 'Alat muzik India termasuk pullangkulal, talam, mattalam dan veenai.'),
(428, 4, 'Apakah tarian tradisional kaum India?', 'Bharatanatyam', 'Tarian Zapin', 'Tarian Sumazau', 'Tarian Ngajat', 'A', 'Tarian klasik India.', 'Tarian tradisional kaum India ialah bharatanatyam.'),
(429, 4, 'Alat muzik manakah ialah alat muzik tradisional Sarawak?', 'Veenai', 'Gendang cina', 'Tongkungan', 'Sape', 'D', 'Alat petik Sarawak.', 'Alat muzik Sarawak termasuk sape, engkerurai dan engkerumong.'),
(430, 4, 'Apakah tarian tradisional Sarawak?', 'Sumazau', 'Bharatanatyam', 'Ngajat', 'Zapin', 'C', 'Tarian perang kaum Sarawak.', 'Tarian tradisional Sarawak ialah ngajat.'),
(431, 4, 'Apakah tarian tradisional dan alat muzik Sabah?', 'Ngajat dengan sape dan engkerurai', 'Zapin dengan gambus dan geduk', 'Makyung dengan geduk dan nafiri', 'Sumazau dengan kulintangan', 'D', 'Pasangan alat dan tarian Sabah.', 'Tarian Sabah ialah sumazau, dengan alat muzik seperti kulintangan, sompotan, tongkungan dan tontog.'),
(432, 4, 'Permainan manakah dimainkan di anjung?', 'Sepak raga', 'Wau', 'Congkak', 'Kabaddi', 'C', 'Dimainkan di atas papan.', 'Permainan anjung termasuk congkak, batu seremban, go atau weiqi, yoyo cina, chaturangam dan paramapadham.'),
(433, 4, 'Permainan manakah ialah permainan anjung kaum Cina?', 'Kabaddi lama', 'Gasing besar', 'Go atau weiqi', 'Chap teh baru', 'C', 'Permainan papan strategi.', 'Go atau weiqi ialah permainan anjung kaum Cina.'),
(434, 4, 'Permainan manakah ialah permainan anjung kaum India?', 'Kabaddi dan sepak raga di laman', 'Chaturangam dan paramapadham', 'Wau dan tibau di kawasan lapang', 'Congkak dan gasing di dalam rumah', 'B', 'Dua permainan papan India.', 'Chaturangam dan paramapadham ialah permainan anjung.'),
(435, 4, 'Permainan manakah dimainkan di laman?', 'Congkak', 'Gasing', 'Paramapadham', 'Sepak raga', 'D', 'Dimainkan dengan bola rotan.', 'Permainan laman termasuk sepak raga, chap teh dan kabaddi.'),
(436, 4, 'Apakah permainan laman yang berasal dari India?', 'Wau', 'Kabaddi', 'Sepak manggis', 'Tibau', 'B', 'Permainan menangkap pasukan lawan.', 'Kabaddi ialah permainan laman yang dimainkan oleh kaum India.'),
(437, 4, 'Permainan manakah dimainkan di kawasan lapang?', 'Batu seremban', 'Congkak', 'Wau', 'Chap teh', 'C', 'Memerlukan angin kencang.', 'Permainan kawasan lapang termasuk wau, tibau, sepak manggis dan gasing.'),
(438, 4, 'Di manakah gasing biasanya dimainkan?', 'Anjung', 'Laman sempit', 'Kawasan lapang', 'Dalam rumah sahaja', 'C', 'Memerlukan tanah luas.', 'Gasing dimainkan di kawasan lapang.'),
(439, 4, 'Mengapakah permainan tradisional dimainkan oleh semua kaum bersama-sama?', 'Untuk memisahkan kaum yang berbeza', 'Untuk memupuk perpaduan dan warisan', 'Untuk menggantikan sekolah di kampung', 'Untuk mengelakkan jiran daripada bertemu', 'B', 'Fikirkan faedah kepada masyarakat.', 'Permainan tradisional dikongsi untuk memupuk perpaduan dan mengekalkan warisan.'),
(440, 4, 'Mengapakah Si Luncai dihukum oleh raja?', 'Kerana mencuri labu di dalam istana', 'Kerana mempermain-mainkan raja', 'Kerana memberontak bersama semua pembesar', 'Kerana melarikan diri dari dalam istana', 'B', 'Berkait dengan sikap Si Luncai kepada raja.', 'Si Luncai dihukum kerana mempermain-mainkan raja dan pembesar.'),
(441, 4, 'Apakah yang dilakukan oleh pesuruh raja kepada Si Luncai?', 'Memenjarakannya di menara paling tinggi', 'Menghalaunya jauh ke dalam hutan belantara', 'Membawanya semula ke istana raja sahaja', 'Memasukkannya ke dalam guni di perahu', 'D', 'Hukuman melibatkan perahu.', 'Si Luncai dimasukkan ke dalam guni di atas perahu.'),
(442, 4, 'Bagaimanakah Si Luncai menipu pesuruh raja?', 'Menyanyi lagu supaya mereka leka', 'Berpura-pura sakit', 'Menyorok di bawah perahu', 'Meminta tolong daripada nelayan', 'A', 'Pesuruh raja berasa terhibur.', 'Si Luncai menyanyi lagu ''Si Luncai terjun dengan labu-labunya, biarkan! biarkan!'' sehingga pesuruh raja leka.'),
(443, 4, 'Apakah yang dimasukkan oleh Si Luncai ke dalam guni sebelum terjun?', 'Batu', 'Sagu', 'Kayu', 'Labu', 'D', 'Sebutan dalam namanya sendiri.', 'Si Luncai mengisi labu ke dalam guni lalu terjun dan berenang dengan labu air.'),
(444, 4, 'Siapakah dua puteri dalam Legenda Santubong?', 'Puteri Gunung Ledang dan Puteri Santubong', 'Puteri Santubong dan Puteri Sejinjang', 'Puteri Sejinjang dan Puteri Serapi', 'Puteri Serapi dan Puteri Talang', 'B', 'Satu menenun, satu menumbuk padi.', 'Puteri Santubong menenun, Puteri Sejinjang menumbuk padi.'),
(445, 4, 'Mengapakah dua puteri diturunkan dari kayangan dalam Legenda Santubong?', 'Untuk mencari Putera Serapi dari Matang', 'Untuk mendamaikan Pasir Kuning dan Pasir Putih', 'Untuk menenun pakaian bagi raja kayangan', 'Untuk membina Gunung Santubong yang tinggi', 'B', 'Dua kampung berselisih.', 'Mereka diturunkan dari kayangan untuk mendamaikan kampung Pasir Kuning dan Pasir Putih.'),
(446, 4, 'Mengapakah Puteri Santubong dan Puteri Sejinjang bertelingkah?', 'Kerana berebut hasil padi di kampung', 'Kerana berebut kain tenunan di kayangan', 'Kerana sama-sama menyukai Putera Serapi', 'Kerana tersilap membina rumah di gunung', 'C', 'Putera dari Matang.', 'Mereka menyukai Putera Serapi dari Matang lalu bertelingkah.'),
(447, 4, 'Apakah akibat antan terkena pipi Puteri Santubong?', 'Pulau Kera terbentuk', 'Sungai Liwagu terbentuk', 'Gunung Santubong sumbing', 'Kampung Pasir Putih hilang', 'C', 'Gunung berkait dengan namanya.', 'Antan terkena pipi Santubong lalu Gunung Santubong sumbing.'),
(448, 4, 'Apakah terjadi apabila batang belidah terkena kepala Puteri Sejinjang?', 'Gunung Santubong menjadi sumbing di tengah', 'Dua kampung berbaik semula selepas itu', 'Putera Serapi terjun ke laut kerana malu', 'Menjadi Pulau Kera, Satang dan Talang-talang', 'D', 'Hasilnya ialah pulau.', 'Batang belidah terkena kepala Sejinjang lalu menjadi Pulau Kera, Pulau Satang dan Pulau Talang-talang.'),
(449, 4, 'Legenda Nunuk Ragang menceritakan tentang kemunculan kaum di mana?', 'Tambunan dan Ranau, Sabah', 'Kuching dan Sibu, Sarawak', 'Melaka dan Kuantan', 'Kuala Terengganu dan Kota Bharu', 'A', 'Berkait dengan Sungai Liwagu.', 'Legenda Nunuk Ragang menceritakan kemunculan pelbagai kaum di Tambunan dan Ranau, Sabah.'),
(450, 4, 'Apakah yang membawa penduduk Sungai Liwagu terbang dalam Legenda Nunuk Ragang?', 'Ayam gergasi merah bertaji emas', 'Burung helang bersayap perak', 'Rama-rama gergasi', 'Naga bersisik biru', 'A', 'Seekor burung yang besar.', 'Ayam gergasi merah bertaji emas membawa penduduk terbang; di mana sayapnya dikibar, di situ mereka membina petempatan dan dialek sendiri.');
